+    fn move_visual_selection(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(selection) = self.visual_selection.as_mut() else {
+            return;
+        };
+        if selection.rows.is_empty() {
+            return;
+        }
+        let max_row = selection.rows.len().saturating_sub(1) as isize;
+        let row = (selection.head.row as isize + row_delta).clamp(0, max_row) as usize;
+        let max_column = row_char_len(&selection.rows[row]).saturating_sub(1) as isize;
+        let column = if selection.kind == VisualSelectionKind::Line {
+            0
+        } else {
+            (selection.head.column as isize + column_delta).clamp(0, max_column) as usize
+        };
+        selection.head = VisualPosition { row, column };
