+        let (inner_width, inner_height) = self.pane_inner_size(selection.focus)?;
+        if inner_width == 0 || inner_height == 0 {
+            return None;
+        }
+        let row = selection.head.row.min(usize::from(inner_height.saturating_sub(1)));
+        let column = selection
+            .head
+            .column
+            .min(usize::from(inner_width.saturating_sub(1)));
+        Some((
+            origin_row.saturating_add(row as u16),
+            origin_column.saturating_add(column as u16),
+        ))
+    }
