+        let Some((origin_column, origin_row)) = self.pane_inner_origin(selection.focus) else {
+            return;
+        };
+        let Some((inner_width, inner_height)) = self.pane_inner_size(selection.focus) else {
+            return;
+        };
+        let inner_width = usize::from(inner_width);
+        let inner_height = usize::from(inner_height);
+        for row in 0..inner_height.min(selection.rows.len()) {
+            let line_len = row_char_len(&selection.rows[row]);
+            let Some(range) = selection.highlight_range_for_row(row, line_len, inner_width) else {
+                continue;
+            };
+            for column in range.start.min(inner_width)..range.end.min(inner_width) {
+                let x = origin_column.saturating_add(column as u16).saturating_sub(1);
+                let y = origin_row.saturating_add(row as u16).saturating_sub(1);
+                if x < buffer.area.width && y < buffer.area.height {
+                    buffer.get_mut(x, y).modifier.insert(Modifier::REVERSED);
+                }
