+
+impl VisualSelection {
+    fn row_bounds(&self) -> (usize, usize) {
+        ordered_pair(self.anchor.row, self.head.row)
+    }
+
+    fn selected_text(&self, kind: VisualSelectionKind) -> String {
+        let (first_row, last_row) = self.row_bounds();
+        let mut copied = Vec::new();
+        for row in first_row..=last_row {
+            let Some(line) = self.rows.get(row) else {
+                continue;
+            };
+            if kind == VisualSelectionKind::Line {
+                copied.push(line.clone());
+            } else if let Some(range) = self.copy_range_for_row(row, row_char_len(line), kind) {
+                copied.push(chars_in_range(line, range));
+            }
+        }
+        copied.join("\n")
+    }
+
+    fn copy_range_for_row(
+        &self,
+        row: usize,
+        line_len: usize,
+        kind: VisualSelectionKind,
+    ) -> Option<Range<usize>> {
+        let (first_row, last_row) = self.row_bounds();
+        if row < first_row || row > last_row {
+            return None;
+        }
+        match kind {
+            VisualSelectionKind::Line => Some(0..line_len),
+            VisualSelectionKind::Block => {
+                let (start, end) = ordered_pair(self.anchor.column, self.head.column);
+                Some(start.min(line_len)..end.saturating_add(1).min(line_len))
+            }
+            VisualSelectionKind::Character => {
+                let max = line_len.saturating_sub(1);
+                if self.anchor.row == self.head.row {
+                    let (start, end) = ordered_pair(self.anchor.column, self.head.column);
+                    Some(start.min(line_len)..end.min(max).saturating_add(1).min(line_len))
+                } else if row == self.anchor.row {
+                    Some(self.anchor.column.min(line_len)..line_len)
+                } else if row == self.head.row {
+                    Some(0..self.head.column.min(max).saturating_add(1).min(line_len))
+                } else {
+                    Some(0..line_len)
+                }
+            }
+        }
+    }
+
+    fn highlight_range_for_row(
+        &self,
+        row: usize,
+        line_len: usize,
+        width: usize,
+    ) -> Option<Range<usize>> {
+        if self.kind == VisualSelectionKind::Line {
+            let (first_row, last_row) = self.row_bounds();
+            return (row >= first_row && row <= last_row).then_some(0..width.max(1));
+        }
+        let range = self.copy_range_for_row(row, line_len, self.kind)?;
+        if range.is_empty() {
+            Some(range.start..range.start.saturating_add(1))
+        } else {
+            Some(range)
+        }
+    }
+}
+
+fn clamp_visual_position(
+    position: VisualPosition,
+    rows: &[String],
+    kind: VisualSelectionKind,
+) -> VisualPosition {
+    let row = position.row.min(rows.len().saturating_sub(1));
+    let column = if kind == VisualSelectionKind::Line {
+        0
+    } else {
+        position.column.min(row_char_len(&rows[row]).saturating_sub(1))
+    };
+    VisualPosition { row, column }
+}
+
+fn ordered_pair(left: usize, right: usize) -> (usize, usize) {
+    if left <= right {
+        (left, right)
+    } else {
+        (right, left)
+    }
+}
+
+fn row_char_len(row: &str) -> usize {
+    row.chars().count()
+}
+
+fn chars_in_range(text: &str, range: Range<usize>) -> String {
+    text.chars()
+        .skip(range.start)
+        .take(range.end.saturating_sub(range.start))
+        .collect()
+}
+
+fn wrap_text_rows(content: &str, width: u16) -> Vec<String> {
+    let width = usize::from(width.max(1));
+    let mut rows = Vec::new();
+    for line in content.lines() {
+        if line.is_empty() {
+            rows.push(String::new());
+            continue;
+        }
+        let chars = line.chars().collect::<Vec<_>>();
+        for chunk in chars.chunks(width) {
+            rows.push(chunk.iter().collect());
+        }
+    }
+    if rows.is_empty() {
+        rows.push(String::new());
+    }
+    rows
+}

